  void sse_encode_ui_event(UiEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case UiEvent_State(field0: final field0):
        sse_encode_i_32(0, serializer);
        sse_encode_box_autoadd_ui_player_snapshot(field0, serializer);
      case UiEvent_Position(seconds: final seconds, duration: final duration):
        sse_encode_i_32(1, serializer);
        sse_encode_f_64(seconds, serializer);
        sse_encode_opt_box_autoadd_f_64(duration, serializer);
      case UiEvent_LibraryChanged():
        sse_encode_i_32(2, serializer);
      case UiEvent_ScanProgress(
        scanned: final scanned,
        total: final total,
        done: final done,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_u_64(scanned, serializer);
        sse_encode_u_64(total, serializer);
        sse_encode_bool(done, serializer);
      case UiEvent_Error(field0: final field0):
        sse_encode_i_32(4, serializer);
        sse_encode_String(field0, serializer);
    }
  }

